import re,json
r=json.load(open('result.json'))
for i,(svg,e) in enumerate(r):
    if svg and 'becomes' in svg:
        # find pieces around
        for m in re.finditer(r"<text[^>]*>[^<]*(?:<tspan[^>]*>[^<]*</tspan>[^<]*)*</text>",svg):
            t=m.group(0)
            if any(ord(c)>127 or c in '6=7' for c in re.sub(r'<[^>]+>','',t)) and len(t)<300: print(i,ascii(t))
        print(re.findall(r'text\.(f\d+) \{font-family:([^;]+);font-size:([\d.]+)px\}',svg))
        break
E

