                if fam not in z: continue
                # chunks: split at tspans
                chunks=[html.unescape(x) for x in re.split(r'<[^>]+>',m.group(3))]
                for ch in chunks:
                    for j,c in enumerate(ch):
                        if c in z[fam]:
                            kind='alone' if all(x in z[fam] for x in ch) else ('first' if j==0 else 'inner')
                            tot[(fam,'U+%04X'%ord(c),kind)]+=1; where[(slug,i+1,fam,'U+%04X'%ord(c),kind)]+=1
    for k,v in sorted(tot.items()): print(' ',k,v)
    json.dump([list(k)+[v] for k,v in sorted(where.items())],open(os.path.basename(work)+'-where.json','w'))
print(attrs)
